package com.arena.core.publicclub;
import com.arena.core.training.AcademyAuthorization;import com.arena.core.sessions.*;import com.arena.core.checkin.*;import com.arena.core.exception.*;
import java.time.*;import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;import java.text.Normalizer;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.oauth2.jwt.Jwt;
@Service @Transactional @RequiredArgsConstructor
public class ClubCustomerService {
 private final com.arena.core.repository.CustomerRepository tenants;private final AcademyAuthorization auth;private final ClubCustomerRepository customers;private final ClubCustomerVisitRepository visits;private final AcademyRunningSessionRepository sessions;private final FacilityCustomerCheckinRepository checkins;private final ClubReservationRequestRepository reservations;
 public record View(Long id,String name,String mobile,String verification,Instant firstVisit,Instant lastVisit,long visitCount,Instant createdAt,Instant updatedAt){@Override public String toString(){return "CustomerView[id="+id+",personalDetails=redacted]";}}
 public static String hash(String text){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 public static String mobile(String raw){String v=raw==null?"":raw.replaceAll("[\\s()\\-]","");if(!v.matches("\\+[1-9][0-9]{7,14}"))throw new ArenaOpsException(ErrorCode.INVALID_REQUEST);return v;}
 public static String name(String raw){String n=Normalizer.normalize(raw==null?"":raw.strip(),Normalizer.Form.NFC);if(n.isBlank()||n.length()>100||n.codePoints().anyMatch(Character::isISOControl))throw new ArenaOpsException(ErrorCode.INVALID_REQUEST);return n;}
 public static String checkinMobile(String raw){String local=raw==null?"":raw.replaceAll("[\\s()\\-]","");String n=mobile(local.matches("[6-9][0-9]{9}")?"+91"+local:raw);if(n.startsWith("+91")&&!n.matches("\\+91[6-9][0-9]{9}"))throw new ArenaOpsException(ErrorCode.INVALID_REQUEST);return n;}
 /** Operational session cards receive a masked contact only, never the customer profile. */
 public String sessionMobile(Long academy,Long session){return visits.findByAcademyIdAndSessionId(academy,session).flatMap(v->customers.findById(v.getCustomerId())).filter(c->academy.equals(c.getAcademyId())&&c.getDeletedAt()==null).map(ClubCustomer::getMobile).filter(m->m!=null&&m.length()>=4).map(m->"••••••"+m.substring(m.length()-4)).orElse(null);}
 public Long visit(Long academy,String rawName,String rawMobile,Long sessionId,Instant started){if(visits.existsBySessionId(sessionId))return null;String name=name(rawName),mobile=mobile(rawMobile),key=hash(name.toLowerCase(Locale.ROOT)+"\n"+mobile);var c=customers.findByAcademyIdAndIdentityKey(academy,key).orElseGet(()->{var x=new ClubCustomer();x.setAcademyId(academy);x.setIdentityKey(key);x.setName(name);x.setMobile(mobile);x.setCreatedAt(Instant.now());return x;});c.setUpdatedAt(Instant.now());customers.saveAndFlush(c);var v=new ClubCustomerVisit();v.setAcademyId(academy);v.setCustomerId(c.getId());v.setSessionId(sessionId);v.setStartedAt(started);visits.save(v);return c.getId();}
 public org.springframework.data.domain.Page<View> list(Jwt jwt,int page){var a=auth.manage(jwt);if(page<0)throw new ArenaOpsException(ErrorCode.INVALID_REQUEST);return customers.findByAcademyIdAndDeletedAtIsNullOrderByUpdatedAtDesc(a.academyId(),org.springframework.data.domain.PageRequest.of(page,25)).map(c->{var rows=visits.findByAcademyIdAndCustomerIdOrderByStartedAtDesc(a.academyId(),c.getId());return new View(c.getId(),c.getName(),c.getMobile(),c.getVerification(),rows.isEmpty()?null:rows.get(rows.size()-1).getStartedAt(),rows.isEmpty()?null:rows.get(0).getStartedAt(),rows.size(),c.getCreatedAt(),c.getUpdatedAt());});}
 public List<ClubCustomerVisit> history(Jwt jwt,Long id){var a=auth.manage(jwt);customers.locked(a.academyId(),id).filter(c->c.getDeletedAt()==null).orElseThrow(()->new ArenaOpsException(ErrorCode.RESOURCE_NOT_FOUND));return visits.findByAcademyIdAndCustomerIdOrderByStartedAtDesc(a.academyId(),id);}
 public void forget(Jwt jwt,Long id){var a=auth.owner(jwt);var c=customers.locked(a.academyId(),id).orElseThrow(()->new ArenaOpsException(ErrorCode.RESOURCE_NOT_FOUND));wipe(c);}
 private void wipe(ClubCustomer c){Long id=c.getId();Long academy=c.getAcademyId();for(var v:visits.findByAcademyIdAndCustomerIdOrderByStartedAtDesc(academy,id)){var s=sessions.findByIdAndAcademyIdForUpdate(v.getSessionId(),academy).orElseThrow();s.setPlayerName(null);sessions.save(s);}checkins.scrubCustomer(academy,id);reservations.scrubCustomer(academy,id);c.setName(null);c.setMobile(null);c.setIdentityKey(hash(UUID.randomUUID().toString()));c.setDeletedAt(Instant.now());c.setUpdatedAt(Instant.now());customers.save(c);}
 public void reservedStarted(AcademyAuthorization.Actor actor,AcademyRunningSession session){reservations.findByAcademyIdAndSessionId(actor.academyId(),session.getId()).filter(r->r.getCustomerName()!=null&&r.getMobile()!=null).ifPresent(r->{var id=visit(actor.academyId(),r.getCustomerName(),r.getMobile(),session.getId(),Instant.now());r.setCustomerId(id);reservations.save(r);});}
 @org.springframework.scheduling.annotation.Scheduled(fixedDelayString="${arena.checkin.cleanup-ms:300000}")public void cleanup(){var before=Instant.now().minus(Duration.ofDays(365));var rows=customers.findTop100ByDeletedAtIsNullAndUpdatedAtBefore(before).stream().sorted(java.util.Comparator.comparing(ClubCustomer::getAcademyId).thenComparing(ClubCustomer::getId)).toList();for(var hint:rows){tenants.findBillingCustomerForUpdate(hint.getAcademyId());customers.locked(hint.getAcademyId(),hint.getId()).filter(c->c.getDeletedAt()==null&&c.getUpdatedAt().isBefore(before)).ifPresent(this::wipe);}}

}
